// Connected components by label propagation.
//
// Every vertex starts as its own component label (IDs[i] = i) and repeatedly
// takes the minimum label among itself and its in-neighbors.  A vertex is put
// on the next frontier whenever its label actually decreased this round, so the
// algorithm terminates once no label changes, i.e. every component has been
// flooded by the smallest vertex id it contains.
//
// prevIDs holds the snapshot of IDs taken at the start of the round.  A vertex
// d is only reported (returns 1) by the update that moves it away from its
// snapshot value, so d appears at most once in the output frontier even though
// several in-neighbors may lower its label in the same round.
#include "ligra.h"

struct CC_F {
  uintE* IDs, *prevIDs;
  CC_F(uintE* _IDs, uintE* _prevIDs) : IDs(_IDs), prevIDs(_prevIDs) {}
  inline bool update(uintE s, uintE d) { //Update: write the smaller label
    uintE origID = IDs[d];
    if(IDs[s] < origID) {
      IDs[d] = min(origID,IDs[s]);
      //only output d the first time its label leaves the round's snapshot
      if(origID == prevIDs[d]) return 1;
    }
    return 0;
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    uintE origID = IDs[d];
    return (writeMin(&IDs[d],IDs[s]) && origID == prevIDs[d]);
  }
  //visit every edge out of the frontier -- labels can always shrink
  inline bool cond (uintE d) { return cond_true(d); }
};

//vertex map function to snapshot the labels at the beginning of a round
struct CC_Vertex_F {
  uintE* IDs, *prevIDs;
  CC_Vertex_F(uintE* _IDs, uintE* _prevIDs) : IDs(_IDs), prevIDs(_prevIDs) {}
  inline bool operator () (uintE i) {
    prevIDs[i] = IDs[i];
    return 1;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long n = GA.n;
  uintE* IDs = newA(uintE,n), *prevIDs = newA(uintE,n);
  {parallel_for(long i=0;i<n;i++) IDs[i] = i;} //initialize unique IDs

  bool* frontier = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;}
  //initial frontier contains all vertices
  vertexSubset Frontier(n,n,frontier);

  long rounds = 0;
  while(!Frontier.isEmpty()){ //iterate until IDs converge
    rounds++;
    vertexMap(Frontier,CC_Vertex_F(IDs,prevIDs));
    vertexSubset output = edgeMap(GA, Frontier, CC_F(IDs,prevIDs));
    Frontier.del();
    Frontier = output;
  }
  Frontier.del();

  //count the number of distinct labels left in IDs by marking each one seen
  bool* seen = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) seen[i] = 0;}
  for(long i=0;i<n;i++) seen[IDs[i]] = 1;
  long components = 0;
  for(long i=0;i<n;i++) if(seen[i]) components++;

  cout << "Components rounds: " << rounds << endl;
  cout << "Components: " << components << endl;

  free(seen); free(IDs); free(prevIDs);
}

